USE prep;
CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE pdfs (id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,title VARCHAR(200) NOT NULL,description TEXT,category VARCHAR(60) DEFAULT 'Others',original_name VARCHAR(255),stored_name VARCHAR(255),file_size BIGINT DEFAULT 0,total_pages INT DEFAULT 0,current_page INT DEFAULT 0,pages_read INT DEFAULT 0,favorite BOOLEAN DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE tasks (id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,title VARCHAR(200) NOT NULL,description TEXT,priority ENUM('Low','Medium','High') DEFAULT 'Medium',deadline DATETIME NULL,estimated_time VARCHAR(50),category VARCHAR(60),status ENUM('Pending','In Progress','Completed') DEFAULT 'Pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE revisions (id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,topic VARCHAR(200) NOT NULL,description TEXT,revision_date DATE NOT NULL,priority ENUM('Low','Medium','High') DEFAULT 'Medium',status ENUM('Pending','Completed') DEFAULT 'Pending',notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE reminders (id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,title VARCHAR(200) NOT NULL,message TEXT,reminder_date DATE NOT NULL,reminder_time TIME NOT NULL,status ENUM('Pending','Sent') DEFAULT 'Pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
